<template>
  <div class="short-term">
    <header class="panel heading"><div><h2>短线异动观察</h2><p>按规则发现变化，保留触发时的数值和依据。</p></div><div class="controls"><button :class="{active:mode==='intraday'}" @click="$emit('modeChange','intraday')">今日盘中关注池</button><button :class="{active:mode==='close'}" @click="$emit('modeChange','close')">所选日收盘扫描</button><button :disabled="loading" @click="refresh">刷新记录</button><button :disabled="scanning || status?.job.status==='running' || status?.job.status==='queued' || !status?.settings.enabled" @click="scan">{{ scanning?'提交中…':'检测最新可用行情' }}</button></div></header>
    <p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" class="message notice" role="status">{{ notice }}</p>
    <section v-if="status" class="panel coverage"><div class="coverage-top"><strong>{{ mode==='intraday'?'盘中分钟检测':'收盘检测' }} · {{ target }}</strong><span>{{ phases[status.phase] || status.phase }}</span><span>{{ status.settings.enabled?'监控已启用':'监控已关闭' }}</span></div><p>{{ status.note }}</p>
      <template v-if="status.coverage"><p v-if="mode==='intraday'">池内 {{ status.coverage.pool }} 只 · 本轮监测 {{ status.coverage.monitored }} 只 · 取得新鲜分钟 {{ status.coverage.fresh }} 只 · 5 分钟样本齐备 {{ status.coverage.move_ready }} 只 · 放量样本齐备 {{ status.coverage.amount_ready }} 只</p><p v-else>市场明细 {{ status.coverage.market_ready?'匹配':'尚未匹配' }} · 有效市场基准 {{ status.coverage.baseline_days }} 日 · 可比板块类别 {{ status.coverage.sector_types_ready }} / 2 · 关注池有效复权报价对 {{ status.coverage.price_pairs }} / {{ status.coverage.stock_pool }}</p><p v-if="status.coverage.latest_bar_time">最新分钟 {{ time(status.coverage.latest_bar_time) }}</p><p class="muted">{{ status.coverage.message }} 扫描记录更新 {{ time(status.coverage.checked_at) }}</p><p v-if="status.coverage.limited" class="notice">有 {{ status.coverage.limited }} 只超出监测上限，可在下方调整上限。</p><p v-for="line in status.coverage.errors || []" :key="line" class="error">{{ line }}</p></template>
      <p v-else>所选日期还没有扫描记录。首次启用后，盘中规则需先积累连续分钟样本；收盘记录由后台定时扫描。</p>
      <p v-if="status.job.status==='running' || status.job.status==='queued'" class="notice">后台扫描{{ status.job.status==='queued'?'已提交':'运行中' }}，正在等待真实执行结果。</p>
    </section>
    <section class="panel"><div class="controls filters"><strong>异动事件 <span v-if="data">{{ data.counts.active }} 条当前触发 · {{ data.counts.unread }} 条未读</span></strong><select v-model="category"><option value="all">全部范围</option><option value="market">市场情绪</option><option value="sector">板块方向</option><option value="stock">自选／关注股</option><option value="etf">宽基 ETF</option></select><label><input type="checkbox" v-model="unreadOnly" />只看未读</label><label><input type="checkbox" v-model="includeResolved" />包含已解除</label><label><input type="checkbox" v-model="includeIgnored" />包含已忽略</label></div>
      <p v-if="loading && !data">正在读取异动记录…</p><p v-else-if="!data?.items.length" class="empty">当前筛选下没有已记录的异动。请结合覆盖情况核对；资料不足时不作正常或异常判断。</p>
      <div class="events"><article v-for="event in data?.items || []" :key="event.id" class="event" :class="{critical:event.level===2,unread:event.unread,resolved:!event.active}"><div class="event-title"><h3>{{ event.title }}</h3><span>{{ !event.active?'条件已解除':event.level===2?'明显异动':'需要关注' }}{{ event.unread?' · 未读':'' }}{{ event.ignored?' · 本轮已忽略':'' }}{{ event.cooling?' · 冷却中':'' }}</span></div><p class="values">触发值 <b>{{ value(event.snapshot.actual) }}{{ event.snapshot.unit }}</b><span>比较基准 {{ value(event.snapshot.baseline) }}{{ event.snapshot.unit }}</span></p><p>{{ event.snapshot.rule }}</p><p class="muted">依据时间 {{ time(event.snapshot.observed_at) }} · 实际记录 {{ time(event.detected_at) }} · {{ event.snapshot.source }}</p><p v-if="!event.notify" class="muted">历史补扫记录，未作为新行情提醒。</p><div class="controls"><button v-if="event.unread" :disabled="!!working" @click="mark(event,'read')">标为已读</button><button v-if="!event.ignored && event.active" :disabled="!!working" @click="mark(event,'ignore')">忽略本轮</button><button v-else-if="event.ignored || !event.unread" :disabled="!!working" @click="mark(event,'reset')">恢复提醒</button><button @click="openHistory(event)">触发历史</button><router-link v-if="event.category==='etf'" :to="{path:'/etfs',query:{view:'funds',date:event.date,fund_batch:event.snapshot.batch_id}}">核对宽基快照 →</router-link><router-link v-if="event.kind.startsWith('seat_flow_')" :to="{path:'/',query:{tab:'dragon-tiger',date:event.date,seat_stock:event.subject,seat_batch:event.snapshot.batch_id}}">核对源披露 →</router-link><router-link v-if="event.category==='stock'" :to="`/stock/${event.subject}`">当前个股详情 →</router-link></div><details v-if="event.snapshot.observations.length"><summary>关联的关注记录（{{ event.snapshot.observations.length }}）</summary><p v-for="observation in event.snapshot.observations" :key="observation.id"><router-link :to="{path:'/review',query:{date:event.date,observation:observation.id}}">{{ observation.date }} 的关注</router-link> · {{ observation.reason }}</p><small>{{ event.snapshot.scope_note }}</small></details>
        <div v-if="historyId===event.id" class="history"><p v-if="historyLoading">正在读取触发历史…</p><template v-else><div v-for="row in history?.items || []" :key="row.id"><b>{{ time(row.snapshot.observed_at) }}</b> · 第 {{ row.cycle }} 轮 · {{ row.active?'触发':'解除' }} · {{ value(row.snapshot.actual) }}{{ row.snapshot.unit }}<p>{{ row.snapshot.rule }}</p></div><div v-if="history && history.pages>1" class="controls"><button :disabled="history.page<=1" @click="loadHistory(history.page-1)">上一页</button><span>{{ history.page }}/{{ history.pages }}</span><button :disabled="history.page>=history.pages" @click="loadHistory(history.page+1)">下一页</button></div></template></div>
      </article></div><div v-if="data && data.pages>1" class="controls pager"><button :disabled="page<=1 || loading" @click="page--">上一页</button><span>{{ data.page }} / {{ data.pages }} · {{ data.total }} 条</span><button :disabled="page>=data.pages || loading" @click="page++">下一页</button></div>
    </section>
    <details class="panel settings" @toggle="settingsToggle"><summary>检测范围与阈值</summary><form v-if="form" @submit.prevent="saveSettings"><fieldset :disabled="saving"><label class="enabled"><input type="checkbox" v-model="form.enabled" />启用后台监测</label><div class="setting-grid"><label>最多监测个股数（1–200）<input type="number" min="1" max="200" step="1" v-model.number="form.max_stocks" required /></label><label v-for="field in fields" :key="field.key">{{ field.label }}<input type="number" :min="field.min" :max="field.max" :step="field.step" v-model="form[field.key]" required /></label></div><p>盘中监控使用当前自选和待验证关注，超出上限时优先纳入关注池。市场和板块规则使用收盘资料；历史回看保留原始触发快照。阈值是观察规则，不表示买卖建议或预测。</p><button type="submit">{{ saving?'保存中…':'保存检测配置' }}</button></fieldset></form></details>
  </div>
</template>
<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {fetchShortTermStatus,fetchShortTermEvents,fetchShortTermHistory,scanShortTerm,setShortTermState,saveShortTermSettings} from '../../api/client'
import type {ShortTermStatus,ShortTermEvents,ShortTermEvent,ShortTermSettings} from '../../api/client'
import {createLatestLoader} from '../../utils/latestLoader'
const props=defineProps<{date:string;mode:'intraday'|'close'}>(),emit=defineEmits<{modeChange:[mode:'intraday'|'close'];changed:[]}>()
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date()),target=computed(()=>props.mode==='intraday'?today:props.date)
const status=ref<ShortTermStatus|null>(null),data=ref<ShortTermEvents|null>(null),loading=ref(false),error=ref(''),notice=ref(''),scanning=ref(false),working=ref(''),saving=ref(false)
const category=ref('all'),unreadOnly=ref(false),includeResolved=ref(false),includeIgnored=ref(false),page=ref(1)
const form=ref<ShortTermSettings|null>(null),settingsOpen=ref(false),historyId=ref(0),history=ref<Awaited<ReturnType<typeof fetchShortTermHistory>>|null>(null),historyLoading=ref(false)
const phases:Record<string,string>={trading:'连续交易时段',closing:'收盘分钟补齐',closed:'已收盘',break:'午间休市',before_open:'开盘前',holiday:'非交易日',unknown:'交易日历待确认'}
const fields:{key:'move_5m_pct'|'critical_5m_pct'|'minute_amount_multiple'|'minute_amount_floor'|'daily_move_pct'|'daily_amount_multiple';label:string;min:number;max:number;step:number}[]=[{key:'move_5m_pct',label:'5 分钟价格变化绝对值（%）',min:.1,max:20,step:.1},{key:'critical_5m_pct',label:'5 分钟明显异动（%）',min:.1,max:30,step:.1},{key:'minute_amount_multiple',label:'分钟成交额放大倍数',min:1.1,max:20,step:.1},{key:'minute_amount_floor',label:'分钟成交额最低值（元）',min:0,max:1e9,step:1e6},{key:'daily_move_pct',label:'收盘复权变化绝对值（%）',min:.1,max:50,step:.1},{key:'daily_amount_multiple',label:'收盘成交额放大倍数',min:1.1,max:20,step:.1}]
let disposed=false,timer:ReturnType<typeof setInterval>|undefined
const loader=createLatestLoader<{status:ShortTermStatus;events:ShortTermEvents}>({pending:value=>loading.value=value,reject:()=>error.value='异动记录读取失败，请刷新重试。',resolve:value=>{status.value=value.status;data.value=value.events;page.value=value.events.page;if(!settingsOpen.value)form.value={...value.status.settings};emit('changed')}})
const historyLoader=createLatestLoader<Awaited<ReturnType<typeof fetchShortTermHistory>>>({pending:value=>historyLoading.value=value,resolve:value=>history.value=value,reject:()=>error.value='触发历史读取失败，请重试。'})
function value(text:string){const number=Number(text);return Number.isFinite(number)?number.toLocaleString('zh-CN',{maximumFractionDigits:2}):text}
function time(text?:string){return text?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(text)):'—'}
function message(e:any,fallback:string){return typeof e?.response?.data?.detail==='string'?e.response.data.detail:fallback}
async function refresh(){error.value='';const date=target.value,mode=props.mode;return loader.load(async signal=>{const [status,events]=await Promise.all([fetchShortTermStatus(date,mode,signal),fetchShortTermEvents({date,mode,category:category.value,unread_only:unreadOnly.value,include_resolved:includeResolved.value,include_ignored:includeIgnored.value,page:page.value},signal)]);return {status,events}})}
async function scan(){if(scanning.value)return;scanning.value=true;error.value='';notice.value='';try{const result=await scanShortTerm();if(disposed)return;notice.value=result.accepted?'后台扫描已提交，正在等待执行结果。':'已复用正在执行或刚提交的扫描任务。';await refresh()}catch(e){if(!disposed)error.value=message(e,'扫描提交结果尚未确认，请刷新核对。')}finally{if(!disposed)scanning.value=false}}
async function mark(event:ShortTermEvent,action:'read'|'ignore'|'reset'){const scope=target.value+props.mode;working.value=String(event.id);try{await setShortTermState(event.id,event.date,action);if(!disposed&&scope===target.value+props.mode)await refresh()}catch(e){if(!disposed&&scope===target.value+props.mode)error.value=message(e,'处理结果尚未确认，请刷新核对。')}finally{if(!disposed)working.value=''}}
function settingsToggle(event:Event){settingsOpen.value=(event.target as HTMLDetailsElement).open;if(settingsOpen.value&&status.value)form.value={...status.value.settings}}
async function saveSettings(){if(!form.value||saving.value)return;saving.value=true;error.value='';try{const result=await saveShortTermSettings({...form.value});if(disposed)return;form.value=result;notice.value='检测配置已保存，下次后台扫描生效；历史触发快照保留。';await refresh()}catch(e){if(!disposed)error.value=message(e,'配置保存失败，请检查阈值范围及明显异动阈值。')}finally{if(!disposed)saving.value=false}}
function loadHistory(page=1){return historyLoader.load(signal=>fetchShortTermHistory(historyId.value,target.value,page,signal))}
function openHistory(event:ShortTermEvent){if(historyId.value===event.id){historyId.value=0;historyLoader.cancel();return}historyId.value=event.id;history.value=null;loadHistory()}
watch(()=>[props.date,props.mode],()=>{loader.cancel();historyLoader.cancel();historyId.value=0;data.value=null;status.value=null;page.value=1;refresh()})
watch([category,unreadOnly,includeResolved,includeIgnored],()=>{page.value=1;refresh()})
watch(page,()=>{if(!loading.value)refresh()})
onMounted(()=>{refresh();timer=setInterval(()=>{if(!loading.value&&!saving.value&&!document.hidden)refresh()},15000)})
onUnmounted(()=>{disposed=true;loader.dispose();historyLoader.dispose();if(timer)clearInterval(timer)})
</script>
<style scoped>
.short-term{display:grid;gap:18px;color:#d1d5db}.panel{border:1px solid #29364b;background:#111827;border-radius:10px;padding:22px}.heading,.event-title,.coverage-top,.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;justify-content:space-between}h2{margin:0;font-size:18px;color:#eef2ff}h3{margin:0;font-size:15px;color:#e5e7eb}p{font-size:12px;line-height:1.9;overflow-wrap:anywhere}.controls{justify-content:flex-start}button,select,input{background:#172338;border:1px solid #3b4e69;color:#cbd5e1;border-radius:5px;padding:7px 10px;font-size:12px}button{cursor:pointer}button:disabled{opacity:.4;cursor:default}button.active{background:#245bb4;color:white}.error{color:#fca5a5}.notice{color:#fcd38b}.message{padding:12px;border:1px solid #344257;border-radius:6px;margin:0}.muted,small{color:#94a3b8;font-size:11px}.coverage-top span{font-size:12px;color:#93c5fd}.filters{margin-bottom:18px}.filters strong{font-size:14px}.filters strong span{font-size:11px;font-weight:400;color:#94a3b8}.filters label{font-size:12px;display:flex;align-items:center;gap:5px}.events{display:grid;gap:14px}.event{padding:18px;background:#0c1626;border:1px solid #2c405c;border-left:3px solid #527aab;border-radius:7px}.event.unread{border-left-color:#fbbf24}.event.critical{border-left-color:#f87171}.event.resolved{opacity:.7}.event-title span{color:#a5b4cb;font-size:11px}.values{display:flex;gap:24px;flex-wrap:wrap}.values b{font-size:20px;color:#e2e8f0;margin-left:8px}.values span{color:#94a3b8}a{font-size:12px;color:#93c5fd;text-decoration:none}details{margin-top:12px}summary{cursor:pointer;font-size:12px;color:#93b9e5}.history{border-top:1px solid #344257;padding-top:12px;margin-top:12px;font-size:12px}.history>div{padding:8px 0}.pager{justify-content:center;margin-top:18px}.empty{color:#94a3b8;padding:20px;font-size:13px}.setting-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:20px}.setting-grid label{font-size:12px;display:flex;flex-direction:column;gap:8px}.settings fieldset{padding:16px 0 0;border:0}.enabled{font-size:13px}.settings p{color:#94a3b8}@media(max-width:800px){.panel{padding:16px}.setting-grid{grid-template-columns:1fr}.event-title{align-items:flex-start}.values{gap:8px;flex-direction:column}}
</style>
